[TestClass]
public class PaymentGatewayGeneralTests
{
    [TestMethod]
    public void PaymentGateway_CanBeInstantiated()
    {
        // Arrange & Act
        var gateway = new Payments.PaymentGateway();

        // Assert
        Assert.IsNotNull(gateway);
    }

    [TestMethod]
    public void ChargeResult_Record_StoresProperties()
    {
        // Arrange & Act
        var result = new ChargeResult("ch_test_123", true);

        // Assert
        Assert.AreEqual("ch_test_123", result.ChargeId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public void ChargeResult_Record_FailureCase()
    {
        // Arrange & Act
        var result = new ChargeResult("", false);

        // Assert
        Assert.AreEqual("", result.ChargeId);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public void RefundResult_Record_StoresProperties()
    {
        // Arrange & Act
        var result = new RefundResult("rf_test_456", true);

        // Assert
        Assert.AreEqual("rf_test_456", result.RefundId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public void RefundResult_Record_FailureCase()
    {
        // Arrange & Act
        var result = new RefundResult("", false);

        // Assert
        Assert.AreEqual("", result.RefundId);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public void ChargeResult_Record_EqualityWorks()
    {
        // Arrange
        var result1 = new ChargeResult("ch_same", true);
        var result2 = new ChargeResult("ch_same", true);
        var result3 = new ChargeResult("ch_different", true);

        // Assert
        Assert.AreEqual(result1, result2);
        Assert.AreNotEqual(result1, result3);
    }

    [TestMethod]
    public void RefundResult_Record_EqualityWorks()
    {
        // Arrange
        var result1 = new RefundResult("rf_same", true);
        var result2 = new RefundResult("rf_same", true);
        var result3 = new RefundResult("rf_different", false);

        // Assert
        Assert.AreEqual(result1, result2);
        Assert.AreNotEqual(result1, result3);
    }
}

